#!/usr/bin/env bash
set -euo pipefail

# Run triangle-free split problems through Vampire -> Dedukti -> Dedukit -> Megalodon
# The tri_*.p problems are generated by tools/split_ramsey_triangle.py (not committed).

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
SPLIT_DIR="$ROOT/tests/dedukti_bridge/triangle_split"
# Vampire is not vendored: build it from https://github.com/vprover/vampire and set
# VAMPIRE, or put it on PATH, or at ../vampire/build/vampire beside Mettapedia.
VAMPIRE="${VAMPIRE:-$(command -v vampire || echo "$ROOT/../../vampire/build/vampire")}"
DEDUKIT="$ROOT/../tools/dedukti.py"
PREAMBLE_EGAL="$ROOT/examples/egal/PfgEJun2022Preamble.mgs"
NEQ_LEMMAS="$ROOT/ramsey36/neq_lemmas_pure.mgs"
DK_PRELUDE="$ROOT/tests/dedukti_bridge/dk_prelude.mg"

if [ ! -x "$VAMPIRE" ]; then
  echo "Vampire not found at $VAMPIRE; set VAMPIRE (https://github.com/vprover/vampire)."
  exit 1
fi

if [ -z "$(find "$SPLIT_DIR" -maxdepth 1 -name 'tri_*.p' -print -quit 2>/dev/null)" ]; then
  python3 "$ROOT/../tools/split_ramsey_triangle.py" \
    --source "$ROOT/ramsey36/adj17_triangle_free.tptp" --out-dir "$SPLIT_DIR"
fi

# Caps
: "${DEDUMAXMEM_MB:=8000}"
ulimit -Sv $((DEDUMAXMEM_MB * 1024))

VTIME="${VTIME:-1}"          # per-problem Vampire time limit (seconds)
LIMIT="${LIMIT:-0}"          # process at most LIMIT problems; 0 = all

fail=0
count=0

while IFS= read -r p; do
  base="${p%.p}"
  dk="$base.dk"
  mg="$base.mg"
  combined="$base.combined.mg"
  ((count++))
  if [ "$LIMIT" -ne 0 ] && [ "$count" -gt "$LIMIT" ]; then
    break
  fi
  echo "[${count}] $p"
  # Vampire -> Dedukti
  "$VAMPIRE" -p dedukti --proof_extra full -t "$VTIME" "$p" > "$dk"
  # Dedukit -> Megalodon
  python3 "$DEDUKIT" "$dk" > "$mg"
  cat "$DK_PRELUDE" "$mg" > "$combined"
  # Megalodon check
  if ! "$ROOT/bin/megalodon" -I "$PREAMBLE_EGAL" -I "$NEQ_LEMMAS" "$combined" >/dev/null; then
    echo "  FAILED"
    ((fail++))
  else
    echo "  OK"
  fi
done < <(find "$SPLIT_DIR" -maxdepth 1 -name 'tri_*.p' | sort)

echo "Done. $fail failures out of $count."
if [ "$fail" -ne 0 ]; then
  exit 1
fi
